static TwoWire* husky_wire = nullptr;
static HardwareSerial* husky_serial = nullptr;
static uint8_t husky_rx[16], husky_pos = 0, husky_count = 0, husky_saved = 0;
static uint16_t husky_detected = 0, husky_total = 0, husky_remaining = 0, husky_learned = 0, husky_frame = 0;
static uint32_t husky_started = 0, husky_sent = 0;
static bool husky_ready = false, husky_busy = false, husky_info = false, husky_done = false;
static uint8_t husky_command = 0;
inline uint16_t husky_u16(const uint8_t* data) {
    return uint16_t(data[0]) | (uint16_t(data[1]) << 8);
}
inline uint8_t husky_build(uint8_t command, const uint8_t* data, uint8_t length, uint8_t* frame) {
    if (length > 23) return 0;
    frame[0] = 0x55; frame[1] = 0xAA; frame[2] = 0x11; frame[3] = length; frame[4] = command;
    uint8_t sum = 0;
    for (uint8_t i = 0; i < length; i++) frame[5+i] = data[i];
    for (uint8_t i = 0; i < length+5; i++) sum += frame[i];
    frame[length+5] = sum;
    return length+6;
}
inline bool husky_send(uint8_t command, const uint8_t* data, uint8_t length) {
    uint8_t frame[29]; uint8_t size = husky_build(command, data, length, frame);
    if (!size) return false;
    if (husky_wire) {
        husky_wire->setClock(100000);
        husky_wire->beginTransmission(0x32);
        for (uint8_t i = 0; i < size; i++) husky_wire->write(frame[i]);
        return husky_wire->endTransmission() == 0;
    }
    if (husky_serial) {
        for (uint8_t i = 0; i < size; i++) if (husky_serial->write(frame[i]) != 1) return false;
        return true;
    }
    return false;
}
inline void husky_accept(const char* block) {
    uint8_t length = husky_rx[3], command = husky_rx[4], sum = 0;
    for (uint8_t i = 0; i < length+5; i++) sum += husky_rx[i];
    if (sum != husky_rx[length+5]) return; // Corruption is discarded; the transaction has a deadline.
    if (command == 0x2E && length == 0 && husky_command != 0x20) { husky_done = true; return; }
    if (husky_command != 0x20) return;
    if (command == 0x29 && length == 10 && !husky_info) {
        husky_remaining = husky_u16(husky_rx+5); husky_total = husky_remaining;
        husky_learned = husky_u16(husky_rx+7); husky_frame = husky_u16(husky_rx+9);
        husky_info = true; husky_saved = 0; husky_done = husky_remaining == 0; return;
    }
    if ((command == 0x2A || command == 0x2B) && length == 10 && husky_info && husky_remaining) {
        if (husky_saved < 10) {
            HuskyResult& result = husky_pending[husky_saved++]; result.kind = command;
            for (uint8_t i = 0; i < 5; i++) result.value[i] = husky_u16(husky_rx+5+2*i);
        }
        husky_done = --husky_remaining == 0;
    }
}
inline void husky_byte(uint8_t value, const char* block) {
    if (husky_pos == 0) { if (value == 0x55) husky_rx[husky_pos++] = value; return; }
    if ((husky_pos == 1 && value != 0xAA) || (husky_pos == 2 && value != 0x11)) {
        husky_pos = value == 0x55 ? 1 : 0; return;
    }
    // Only INFO/BLOCK/ARROW (10 bytes) and OK (0 bytes) fit the receive buffer.
    if (husky_pos == 3 && value != 0 && value != 10) { husky_pos = 0; return; }
    husky_rx[husky_pos++] = value;
    if (husky_pos >= 5 && husky_pos == husky_rx[3]+6) { husky_accept(block); husky_pos = 0; }
}
inline void husky_poll(const char* block) {
    if (husky_wire) {
        husky_wire->setClock(100000);
        husky_wire->requestFrom(uint8_t(0x32), uint8_t(16));
        for (uint8_t i = 0; i < 16 && husky_wire->available(); i++) {
            int value = husky_wire->read(); if (value < 0) break; husky_byte(uint8_t(value), block);
        }
    } else if (husky_serial) {
        for (uint8_t i = 0; i < 64 && husky_serial->available(); i++) {
            int value = husky_serial->read(); if (value < 0) break; husky_byte(uint8_t(value), block);
        }
    }
}
inline void husky_reset() {
    husky_ready = false; husky_count = 0; husky_detected = 0; husky_busy = true; husky_command = 0x2C;
    husky_started = millis(); husky_sent = millis()-100; husky_pos = 0; husky_done = false;
