inline bool husky_wait(const char* block) {
    if (rb_failed) return true;
    husky_poll(block);
    if (husky_done) {
        if (husky_command == 0x20) {
            for (uint8_t i = 0; i < husky_saved; i++) husky_results[i] = husky_pending[i];
            husky_count = husky_saved; husky_detected = husky_total;
        } else if (husky_command == 0x2D || husky_command == 0x36 || husky_command == 0x37 || husky_command == 0x33) {
            husky_count = 0; husky_detected = 0;
        } // Algorithm and learning changes invalidate the cached frame.
        husky_busy = false; return true;
    }
    uint32_t timeout = 500;
    if (husky_command == 0x2D || husky_command == 0x36 || husky_command == 0x37) timeout = 2000;
    if (husky_command == 0x2F) timeout = 1000;
    if (husky_command == 0x30 || husky_command == 0x39 || husky_command == 0x32 || husky_command == 0x33) timeout = 5000;
    if (uint32_t(millis() - husky_started) >= timeout) {
        husky_busy = false; rb_fail(block, "No responde HuskyLens: trama incompleta o checksum inválido"); return true;
    }
