inline uint8_t husky_kind(const String& kind) {
    return kind[0] == 'b' ? 0x2A : 0x2B;
}
inline bool husky_integer(float value, uint16_t minimum, uint16_t maximum, const char* block) {
    if (!isfinite(value) || value < minimum || value > maximum || value != floorf(value)) {
        rb_fail(block, "HuskyLens: número o ID fuera de rango, debe ser entero"); return false;
    }
    return true;
}
inline bool husky_match(const HuskyResult& result, uint8_t kind, int32_t id) {
    return result.kind == kind && (id < 0 || (id == 0 ? result.value[4] > 0 : result.value[4] == id));
