inline int husky_nth(float id, uint8_t kind, float n, const char* block) {
    if (!husky_available(block) || !husky_integer(n, 1, 65535, block)) return -1;
    if (id != -1 && !husky_integer(id, 0, 65535, block)) return -1;
    uint16_t found = 0;
    for (uint8_t i = 0; i < husky_count; i++) {
        if (husky_match(husky_results[i], kind, int32_t(id)) && ++found == uint16_t(n)) return i;
    }
    return -1;
}
inline float husky_prop(float id, const String& prop, const String& kind, float n, const char* block) {
    int index = husky_nth(id, husky_kind(kind), n, block);
    return index < 0 ? -1 : husky_results[index].value[prop[0] - '0'];
