inline float husky_counts(float id, const String& kind, const char* block) {
    if (!husky_available(block)) return 0;
    if (id != -1 && !husky_integer(id, 0, 65535, block)) return 0;
    uint8_t count = 0;
    for (uint8_t i = 0; i < husky_count; i++) if (husky_match(husky_results[i], husky_kind(kind), int32_t(id))) count++;
    return count;
}
inline float husky_learned_count(const char* block) {
    return husky_available(block) ? husky_learned : 0;
}
inline bool husky_is_learned(float id, const char* block) {
    return husky_available(block) && husky_integer(id, 1, 65535, block) && id <= husky_learned;
}
inline float husky_center(const String& prop, const String& kind, const char* block) {
    if (!husky_available(block)) return -1;
    int closest = -1; float distance = 0;
    for (uint8_t i = 0; i < husky_count; i++) {
        const HuskyResult& result = husky_results[i];
        if (result.kind != husky_kind(kind)) continue;
        float x = result.value[0], y = result.value[1];
        if (result.kind == 0x2B) { x = (x + result.value[2]) / 2; y = (y + result.value[3]) / 2; }
        float dx = x - 160, dy = y - 120, squared = dx * dx + dy * dy;
        if (closest < 0 || squared < distance) { closest = i; distance = squared; }
    }
    return closest < 0 ? -1 : husky_results[closest].value[prop[0] - '0'];
