inline void husky_number_request(uint8_t command, float number, uint16_t minimum, const char* block) {
    if (!husky_integer(number, minimum, 65535, block)) return;
    uint16_t value = uint16_t(number);
    uint8_t data[2] = { uint8_t(value), uint8_t(value >> 8) };
    husky_request(command, data, 2, block);
}
inline void husky_name(float id, const String& name, const char* block) {
    if (!husky_integer(id, 1, 255, block)) return;
    if (name.length() > 20) { rb_fail(block, "Nombre HuskyLens: máximo 20 bytes ASCII"); return; }
    uint8_t data[23] = {}; data[0] = uint8_t(id); data[1] = uint8_t(name.length() + 1);
    for (uint8_t i = 0; i < name.length(); i++) {
        if (uint8_t(name[i]) == 0 || uint8_t(name[i]) > 127) { rb_fail(block, "Nombre HuskyLens: solo texto ASCII"); return; }
        data[2 + i] = uint8_t(name[i]);
    }
    husky_request(0x2F, data, sizeof data, block);
}
inline int husky_id_nth(float id, uint8_t kind, float n, const char* block) {
    return husky_integer(id, 0, 65535, block) ? husky_nth(id, kind, n, block) : -1;
}
inline float husky_id_prop(float id, const String& prop, const String& kind, float n, const char* block) {
    return husky_integer(id, 0, 65535, block) ? husky_prop(id, prop, kind, n, block) : -1;
}
inline float husky_id_counts(float id, const String& kind, const char* block) {
    return husky_integer(id, 0, 65535, block) ? husky_counts(id, kind, block) : 0;
}

